#!/usr/bin/env bash
#
# A wizard walks the founder through a manual procedure, step by step.
# Generated by the `wizard` skill. The FOUNDER runs it by hand; an agent never does.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# Secret rules this library enforces:
#   - secrets are read with hidden input and are never printed, logged or exported
#   - only NAMES are ever reported, never values
#   - a value is written only to an UNTRACKED, git-ignored file (default apps/api/.env)
#   - live keys (sk_live_, rk_live_ anywhere in a value) are refused everywhere; they go straight from
#     the provider's dashboard to the Render dashboard, never through this script
#   - Render env vars are set in the Render dashboard by the founder; nothing here calls Render

set -euo pipefail
set +a   # an inherited allexport would export every value set with printf -v
umask 077

# xtrace would print every captured value; refuse to run under it.
case $- in *x*) echo "wizard: refusing to run with 'set -x' (it would print secrets)" >&2; exit 1;; esac

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
# Local dev file for test-mode values. Must be untracked AND git-ignored (checked in write_env).
ENV_FILE="${ENV_FILE:-apps/api/.env}"
WRITTEN_ENV=()     # KEY names written to ENV_FILE this run (names only)
DASHBOARD_DONE=()  # names the founder confirmed saving in a dashboard
SKIPPED=()         # things not done

die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do.\n' "$DIM"
  printf '  Secrets are typed hidden and never shown. Stop any time with Ctrl-C and re-run.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser (https only), cross-platform incl. WSL.
open_url() {
  local url="$1"
  [[ "$url" == https://* ]] || die "open_url only opens https URLs"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_valid_key() { [[ "$1" =~ ^[A-Z][A-Z0-9_]*$ ]] || die "bad variable name: $1"; }

# xtrace would print every captured value; checked at startup and again in every
# function that handles a value (someone could enable it mid-run).
_no_xtrace() { case $- in *x*) echo "wizard: refusing to run with 'set -x' (it would print secrets)" >&2; exit 1;; esac; }

# Names that must only be typed hidden. ask() refuses them.
_is_secret_name() { [[ "$1" =~ (SECRET|TOKEN|PASSWORD|PRIVATE|WEBHOOK|API_KEY|KEY$|DATABASE_URL|REDIS_URL|DSN) ]]; }

# Values that must never pass through this script at all. A live key anywhere in
# the value is refused (quotes or a pasted KEY=value line do not hide it).
# whsec_ is the prefix for test AND live webhook secrets, so it needs a confirm.
_refuse_live() {   # $2 = nowhsec: skip the whsec_ confirm (already asked when the value was typed)
  case "$1" in
    *sk_live_*|*rk_live_*)
      die "that looks like a LIVE key. Live keys go from the provider dashboard straight into the Render dashboard; never paste one here." ;;
  esac
  [[ "${2:-}" == nowhsec ]] && return 0
  case "$1" in
    *whsec_*)
      confirm "This looks like a webhook signing secret. Did it come from 'stripe listen' or a TEST-mode endpoint?" \
        || die "only a test-mode webhook secret may be used here" ;;
  esac
}

# Reject CR/LF in a value.
_no_newline() { [[ "$1" != *$'\n'* && "$1" != *$'\r'* ]] || die "value contains a line break"; }

# _has_existing KEY: is KEY already set in ENV_FILE? Status only; the value is never read back.
_has_existing() {
  [[ -f "$ENV_FILE" ]] && grep -qE "^${1}=." "$ENV_FILE"
}

KEPT=()  # names the founder kept (Enter) rather than re-entered

# A non-empty value typed for a key that was kept earlier replaces the kept marker.
_unkeep() { local k n=(); for k in ${KEPT[@]+"${KEPT[@]}"}; do [[ "$k" == "$1" ]] || n+=("$k"); done; KEPT=(${n[@]+"${n[@]}"}); }

_was_kept() { local k; for k in ${KEPT[@]+"${KEPT[@]}"}; do [[ "$k" == "$1" ]] && return 0; done; return 1; }

# ask KEY "Prompt" reads a NON-secret value into $KEY (visible). Refuses secret-looking
# names and secret-looking values (credentialed URLs, sk_/rk_/whsec_ prefixes).
ask() {
  _no_xtrace
  local key="$1" prompt="$2" input=""
  _valid_key "$key"
  _is_secret_name "$key" && die "$key looks like a secret; use ask_secret"
  if _has_existing "$key"; then
    printf '  %s%s%s %s[Enter keeps the value already saved]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  if [[ -n "$input" ]]; then _unkeep "$key"; elif _has_existing "$key"; then KEPT+=("$key"); fi
  _no_newline "$input"
  case "$input" in
    *://*:*@*|sk_*|rk_*|whsec_*) die "that looked like a secret and is now on screen: clear the terminal scrollback and rotate the key" ;;
  esac
  _refuse_live "$input"
  unset "$key"            # never leave an exported variable behind
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" reads a secret with hidden input. Nothing is echoed.
ask_secret() {
  _no_xtrace
  local key="$1" prompt="$2" input=""
  _valid_key "$key"
  if _has_existing "$key"; then
    printf '  %s%s%s %s[Enter keeps the value already saved]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  if [[ -n "$input" ]]; then _unkeep "$key"; elif _has_existing "$key"; then KEPT+=("$key"); fi
  _no_newline "$input"
  _refuse_live "$input"
  unset "$key"
  printf -v "$key" '%s' "$input"
}

# forget KEY... removes captured variables once they are written.
forget() { local k; for k in "$@"; do unset "$k"; done; }

# _guard_env_file refuses any ENV_FILE that git tracks or does not ignore.
_guard_env_file() {
  command -v git >/dev/null 2>&1 || die "git is needed to check that $ENV_FILE is untracked"
  if git ls-files --error-unmatch -- "$ENV_FILE" >/dev/null 2>&1; then
    die "$ENV_FILE is tracked by git; refusing to write a secret there"
  fi
  git check-ignore -q -- "$ENV_FILE" || die "$ENV_FILE is not git-ignored; refusing to write a secret there"
}

_TMP=""
trap '[[ -n "$_TMP" ]] && rm -f -- "$_TMP"' EXIT
trap 'exit 130' INT TERM

# write_env KEY upserts KEY=<value of $KEY> into ENV_FILE (mode 600). It takes the NAME
# only and reads the value by indirection, so a trace or a call line never holds the value.
# A name the founder kept (Enter) is left untouched. Prints the NAME only.
write_env() {
  _no_xtrace
  local key="$1"
  _valid_key "$key"
  if _was_kept "$key"; then
    printf '  %s✓ kept%s %s in %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
    return 0
  fi
  [[ -n "${!key:+x}" ]] || die "$key is empty; nothing to write"
  _no_newline "${!key}"
  _refuse_live "${!key}" nowhsec
  _guard_env_file
  touch "$ENV_FILE"; chmod 600 "$ENV_FILE"
  # Beside the target, named so .gitignore's `.env.*` covers it; removed by the EXIT trap if we stop early.
  _TMP=$(mktemp "$ENV_FILE.wizard.XXXXXX")
  git check-ignore -q -- "$_TMP" || die "temp file $_TMP is not git-ignored"
  grep -vE "^${key}=" "$ENV_FILE" > "$_TMP" || [[ $? -eq 1 ]] || die "could not read $ENV_FILE"
  printf '%s=%s\n' "$key" "${!key}" >> "$_TMP"
  chmod 600 "$_TMP"
  mv "$_TMP" "$ENV_FILE"
  _TMP=""
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# dashboard_set NAME "Where" asks the founder to copy a value from one dashboard
# and paste it into another (e.g. Stripe → Render). The value never touches this script.
dashboard_set() {
  local name="$1" where="$2"
  step "Paste $name into: $where (copy and paste directly; do not type it here)."
  if confirm "Saved $name in $where?"; then
    DASHBOARD_DONE+=("$name")
  else
    SKIPPED+=("$name in $where")
    warn "skipped $name; do it by hand"
  fi
}

finish() {
  _clear
  printf '\n%s%s  ✓ Wizard finished%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} name(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#DASHBOARD_DONE[@]} )) && note "confirmed in a dashboard: ${DASHBOARD_DONE[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=2

banner "Stripe test-mode setup (example)"

# ── Example stage 1: a TEST key kept locally, in the untracked apps/api/.env ──
stage "Stripe: test secret key (local dev)"
say "Test mode only. A live key is refused."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Reveal the test Secret key (starts sk_test_) and copy it."
ask_secret STRIPE_SECRET_KEY "Paste the test secret key (hidden):"
write_env STRIPE_SECRET_KEY
forget STRIPE_SECRET_KEY

# ── Example stage 2: a value that belongs on Render, set in the dashboard ─────
stage "Render: STRIPE_PRICE_ID"
open_url "https://dashboard.stripe.com/test/products"
step "Open the product, copy the Price ID (price_...). It is not a secret."
open_url "https://dashboard.render.com/"
dashboard_set STRIPE_PRICE_ID "the Render API service → Environment"
# ──────────────────────────────────────────────────────────────────────────

finish
